var t=`1024-banh-xeo`;var n=`world-1024`;var s=`VN`;var r=`southeast-asia`;var o=8;var a=43;var l={en:`Banh Xeo`,ua:`Бань сео`};var h={en:`Banh Xeo is a dish from Vietnam prepared with rice flour, coconut milk, pork belly, shrimp. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Бань сео, страва кухні країни В'єтнам, яку готують із таких продуктів: рисове борошно, кокосове молоко, свиняча грудинка, креветка. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var u=[{en:`Whisk the listed batter ingredients until smooth. Let the mixture rest briefly so the flour hydrates.`,ua:`Збийте складники рідкого тіста до однорідності. Дайте суміші коротко відпочити, щоб борошно увібрало вологу.`,t:[`mixing`,`whisking`],m:10,i:[[`rice-flour`,250,`g`],[`coconut-milk`,260,`ml`],[`water`,300,`ml`],[`ground-turmeric`,4,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`pork-belly`,250,`g`],[`shrimp`,300,`g`],[`green-onion`,40,`g`]]},{en:`Pour a thin turmeric rice batter into a hot oiled pan, add already cooked pork and shrimp with bean sprouts, and cook until the bánh xèo crust is crisp; fold in half.`,ua:`Налийте тонкий шар рисового тіста з куркумою на гарячу змащену сковороду, додайте готові свинину, креветки й паростки, підсмажте до хрусткості та складіть навпіл.`,t:[`pan-frying`],m:20,i:[[`sunflower-oil`,65,`ml`],[`mung-bean-sprouts`,230,`g`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`lettuce`,200,`g`],[`mint`,30,`g`],[`fish-sauce`,40,`ml`],[`lime-juice`,40,`ml`]]}];var m={slug:t,id:n,country:`VN`,region:r,servings:8,minutes:43,title:l,text:h,steps:u};export{s as country,m as default,n as id,a as minutes,r as region,o as servings,t as slug,u as steps,h as text,l as title};